CREATE TABLE admins(id CHAR(36) PRIMARY KEY,email VARCHAR(160) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','staff') NOT NULL DEFAULT 'admin',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE schedule_templates(id CHAR(36) PRIMARY KEY,weekday TINYINT NOT NULL,label VARCHAR(30) NOT NULL,capacity INT NOT NULL DEFAULT 40,active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_day_label(weekday,label));
CREATE TABLE time_slots(id CHAR(36) PRIMARY KEY,template_id CHAR(36) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,capacity INT NOT NULL DEFAULT 40,active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_slot(template_id,start_time,end_time),FOREIGN KEY(template_id) REFERENCES schedule_templates(id) ON DELETE CASCADE);
CREATE TABLE reservations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reservation_code VARCHAR(30) UNIQUE NOT NULL,reservation_date DATE NOT NULL,slot_id CHAR(36) NOT NULL,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,whatsapp VARCHAR(30) NOT NULL,email VARCHAR(160),whatsapp_consent TINYINT(1) DEFAULT 0,status ENUM('confirmed','cancelled','attended','no_show') DEFAULT 'confirmed',source VARCHAR(30) DEFAULT 'web',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,cancelled_at TIMESTAMP NULL,INDEX idx_date_slot(reservation_date,slot_id),FOREIGN KEY(slot_id) REFERENCES time_slots(id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id CHAR(36) NULL,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id VARCHAR(80),metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
